using ProMaxx2.QA.Application.Common;using ProMaxx2.QA.Application.Projects;using ProMaxx2.QA.Domain.TestManagement;
namespace ProMaxx2.QA.Application.TestManagement;
public sealed record SuiteCaseDto(Guid TestCaseId,string TestCaseCode,string Title,string Priority,int SortOrder,bool IsRequired);public sealed record SuiteCycleRefDto(Guid TestCycleId,string CycleCode,string CycleName,string Status,bool IsDeleted,string?BuildNumber,DateTime?StartDate,DateTime?EndDate,string?OwnerName,int CaseCount,int ExecutedCount,decimal ProgressPercent);public sealed record TestSuiteDto(Guid TestSuiteId,Guid ProjectId,string SuiteCode,string SuiteName,string?SuiteType,string?Description,string?RiskTier,bool IsActive,int CycleCount,IReadOnlyList<SuiteCaseDto>Cases,IReadOnlyList<SuiteCycleRefDto>LinkedCycles,Guid?CreatedBy,string?CreatedByName,DateTime?CreatedAt);public sealed record SaveTestSuiteRequest(Guid ProjectId,string SuiteCode,string SuiteName,string?SuiteType,string?Description,string?RiskTier,bool IsActive=true);public sealed record AddSuiteCasesRequest(IReadOnlyList<Guid>TestCaseIds,bool IsRequired);public sealed record UpdateSuiteCaseRequest(int SortOrder,bool IsRequired);public sealed record SuiteModuleDto(Guid ModuleId,string ModuleCode,string ModuleName);
public sealed record TestSuiteListDto(Guid TestSuiteId,Guid ProjectId,string SuiteCode,string SuiteName,string?SuiteType,string?Description,string?RiskTier,bool IsActive,int CycleCount,int CaseCount,IReadOnlyList<SuiteModuleDto> Modules,Guid?CreatedBy,string?CreatedByName,DateTime?CreatedAt);
public interface ITestSuiteRepository{Task<PagedResult<TestSuiteListDto>>ListAsync(Guid?projectId,string?search,string?suiteType,string?riskTier,bool?isActive,Guid?moduleId,int page,int size,CancellationToken ct);Task<TestSuiteDto?>GetAsync(Guid id,CancellationToken ct);Task<TestSuiteDto?>GetForAiAsync(Guid id,int maxCases,CancellationToken ct);Task<TestSuite?>FindAsync(Guid id,bool activeOnly,CancellationToken ct);Task<bool>CodeExistsAsync(Guid projectId,string code,Guid?excludeId,CancellationToken ct);Task<bool>NameExistsAsync(Guid projectId,string name,Guid?excludeId,CancellationToken ct);Task<IReadOnlyList<string>>ListCodesAsync(Guid projectId,string prefix,CancellationToken ct);Task DeleteLinkedCyclesAsync(Guid id,CancellationToken ct);Task AddAsync(TestSuite suite,CancellationToken ct);Task AddCasesAsync(Guid id,IReadOnlyList<Guid>caseIds,bool required,CancellationToken ct);Task UpdateCaseAsync(Guid id,Guid caseId,int sortOrder,bool required,CancellationToken ct);Task RemoveCaseAsync(Guid id,Guid caseId,CancellationToken ct);Task DeleteAsync(TestSuite suite,CancellationToken ct);Task SaveAsync(CancellationToken ct);}
public sealed class TestSuiteService(ITestSuiteRepository repository,IProjectRepository projects){public Task<PagedResult<TestSuiteListDto>>ListAsync(Guid?projectId,string?search,string?suiteType,string?riskTier,bool?isActive,Guid?moduleId,int page,int size,CancellationToken ct)=>repository.ListAsync(projectId,search,suiteType,riskTier,isActive,moduleId,page,size,ct);public async Task<TestSuiteDto>GetAsync(Guid id,CancellationToken ct)=>await repository.GetAsync(id,ct)??throw new EntityNotFoundException("Test suite not found.");public Task<TestSuiteDto?>GetForAiAsync(Guid id,int maxCases,CancellationToken ct)=>repository.GetForAiAsync(id,maxCases,ct);public async Task<TestSuiteDto>CreateAsync(SaveTestSuiteRequest r,Guid?userId,CancellationToken ct){var project=await projects.GetAsync(r.ProjectId,ct)??throw new EntityNotFoundException("Project not found.");var code=string.IsNullOrWhiteSpace(r.SuiteCode)?BusinessCodeGenerator.NextAvailable($"{project.ProjectCode}-TS",await repository.ListCodesAsync(r.ProjectId,$"{project.ProjectCode}-TS",ct)):r.SuiteCode.Trim().ToUpperInvariant();if(await repository.CodeExistsAsync(r.ProjectId,code,null,ct))throw new DuplicateCodeException("Suite code already exists.");if(await repository.NameExistsAsync(r.ProjectId,r.SuiteName,null,ct))throw new DuplicateCodeException("Suite name already exists.");var entity=new TestSuite(r.ProjectId,code,r.SuiteName,r.SuiteType,r.Description,r.RiskTier,userId);await repository.AddAsync(entity,ct);await repository.SaveAsync(ct);return(await repository.GetAsync(entity.TestSuiteId,ct))!;}public async Task<TestSuiteDto>UpdateAsync(Guid id,SaveTestSuiteRequest r,CancellationToken ct){var entity=await repository.FindAsync(id,false,ct)??throw new EntityNotFoundException("Test suite not found.");if(!string.IsNullOrWhiteSpace(r.SuiteCode)){var newCode=r.SuiteCode.Trim().ToUpperInvariant();if(newCode!=entity.SuiteCode){if(await repository.CodeExistsAsync(entity.ProjectId,newCode,null,ct))throw new DuplicateCodeException("Suite code already exists.");entity.UpdateCode(newCode);}}if(!string.IsNullOrWhiteSpace(r.SuiteName)&&await repository.NameExistsAsync(entity.ProjectId,r.SuiteName,id,ct))throw new DuplicateCodeException("Suite name already exists.");entity.Update(r.SuiteName,r.SuiteType,r.Description,r.RiskTier,r.IsActive);await repository.SaveAsync(ct);return(await repository.GetAsync(id,ct))!;}public async Task DeactivateAsync(Guid id,CancellationToken ct){var entity=await repository.FindAsync(id,false,ct)??throw new EntityNotFoundException("Test suite not found.");entity.Deactivate();await repository.SaveAsync(ct);}public async Task AddCasesAsync(Guid id,AddSuiteCasesRequest r,CancellationToken ct){_=await repository.FindAsync(id,true,ct)??throw new EntityNotFoundException("Test suite not found.");await repository.AddCasesAsync(id,r.TestCaseIds,r.IsRequired,ct);await repository.SaveAsync(ct);}public async Task UpdateCaseAsync(Guid id,Guid caseId,UpdateSuiteCaseRequest r,CancellationToken ct){await repository.UpdateCaseAsync(id,caseId,r.SortOrder,r.IsRequired,ct);await repository.SaveAsync(ct);}public async Task RemoveCaseAsync(Guid id,Guid caseId,CancellationToken ct){await repository.RemoveCaseAsync(id,caseId,ct);await repository.SaveAsync(ct);}public async Task HardDeleteAsync(Guid id,CancellationToken ct){var entity=await repository.FindAsync(id,false,ct)??throw new EntityNotFoundException("Test suite not found.");await repository.DeleteLinkedCyclesAsync(id,ct);await repository.DeleteAsync(entity,ct);await repository.SaveAsync(ct);}}
